1	// Shared routing surface (config.yaml -> app.shared_surfaces.frontend).
2	// A page is registered by its feature, not listed here: every features/<name>/route.tsx exports a
3	// `route` data declaration, and this module auto-discovers them. Adding a page = a NEW feature route
4	// module, never an edit to this file (DESIGN.md §8).
5	import type { ComponentType } from 'react';
6	
7	export type AppRoute = {
8	  /** Section id. Drives the nav link testid (`nav-<id>`) and selects the active page. */
9	  id: string;
10	  /** Human label shown in the nav. */
11	  label: string;
12	  /** The screen component for this section. */
13	  component: ComponentType;
14	};
